"""Chapter 13 D.C. Circuits: written-answer questions, 5 per level."""
from .. import sketches2 as sk
from ..marker import Pitfall, Point
from .base import written

P = Point
PF = Pitfall

# ---------------------------------------------------------------- L1
written("w13_series_current_rule", 13, 1, "13b",
        stem="Fig. 1 shows a series circuit. State the rule for the current at different points in a series circuit.",
        points=[P("the current is the same at every point", ["same at every point", "same everywhere", "same throughout", "same at all points", "same current", "does not change", "equal at every"])],
        pitfalls=[PF(["current decreases", "gets smaller", "is used up"], "Current is NOT used up: it is the same at every point in a series circuit.")],
        model_answer="In a series circuit the current is the same at every point.",
        hints=["There is only one path for the charge. Can it pile up or get used up anywhere?",
               "Every ammeter in a series circuit reads the same.",
               "State the rule as a sentence."],
        keywords="current same at every point",
        figure=lambda: sk.circuit(series=[("A", "A₁"), ("R", "R"), ("A", "A₂")], emf=""),
        sample_pass=["The current is the same at every point", "it is the same throughout the circuit"],
        sample_fail=["The current decreases after each component", "The current is shared between the components"])

written("w13_parallel_pd_rule", 13, 1, "13e",
        stem="Fig. 1 shows two resistors in parallel. State the rule for the p.d. across the branches of a parallel circuit.",
        points=[P("the p.d. across each branch is the same (equal to the p.d. across the whole combination)", ["same across each branch", "same p.d.", "same for each", "equal p.d.", "same voltage", "each branch has the same", "same as the supply"])],
        pitfalls=[PF(["p.d. is shared", "p.d. is divided", "shared between the branches"], "In PARALLEL the p.d. is the same across every branch; it is in SERIES that it is shared.")],
        model_answer="The p.d. across each branch of a parallel circuit is the same, and equal to the p.d. across the whole parallel combination.",
        hints=["Each branch is connected between the same two points. What does that mean for the p.d.?",
               "Same two points, same difference in potential.",
               "State the rule as a sentence."],
        keywords="same p.d. across each branch",
        figure=lambda: sk.circuit(parallel=[[("R", "R₁")], [("R", "R₂")]], emf=""),
        sample_pass=["The p.d. across each branch is the same", "every branch has the same voltage as the supply"],
        sample_fail=["The p.d. is shared between the branches", "The p.d. is bigger across the larger resistor"])

