        points=[P("the sum of the p.d.s across the components equals the p.d. across the whole circuit (the supply)", ["add up to", "sum of the p.d.s", "p.d.s add", "total p.d.", "equal to the supply", "equals the p.d. across the whole", "shared between", "divided between"])],
        model_answer="In a series circuit the sum of the p.d.s across the separate components is equal to the p.d. across the whole circuit (the supply p.d.).",
