written("w13_pd_shares_proportional", 13, 3, "13c",
        stem="Fig. 1 shows a 2 Ω resistor and a 4 Ω resistor in series with a 12 V battery. Explain how the 12 V is shared between the resistors and give the p.d. across each.",
        points=[P("the same current flows through both resistors (series)", ["same current", "current is the same", "same i"]),
                P("V = I R, so the p.d. is shared in proportion to the resistances: the 4 Ω gets twice the p.d. of the 2 Ω", ["proportional to the resistance", "in proportion", "v = ir", "v = i r", "twice the p.d.", "larger resistor gets more", "ratio 1:2", "1 : 2"]),
                P("4 V across the 2 Ω and 8 V across the 4 Ω (they add to 12 V)", ["4 v", "8 v", "4 and 8", "4 volts", "8 volts"])],
        min_points=2,
        model_answer="The same current flows through both resistors. Since V = I R, the p.d. across each is proportional to its resistance, so the 4 Ω resistor has twice the p.d. of the 2 Ω resistor. The 12 V is therefore shared as 4 V across the 2 Ω and 8 V across the 4 Ω, which add to 12 V.",
        hints=["In series the current is the same. Which equation then links p.d. to resistance?",
               "Same I, so V ∝ R. Split 12 V in the ratio 2 : 4.",
               "Explain the sharing rule and give both p.d.s."],
        keywords="same current, V ∝ R, 4 V and 8 V",
        figure=lambda: sk.circuit(series=[("R", "2 Ω"), ("R", "4 Ω")], emf="12 V"),
        sample_pass=["The same current flows through both so V = IR means the p.d. is proportional to resistance: 4 V across the 2 Ω and 8 V across the 4 Ω",
                     "shared in the ratio 1:2, giving 4 V and 8 V"],
        sample_fail=["6 V across each because the p.d. is shared equally", "12 V across each"])

written("w13_ammeter_low_resistance", 13, 3, "13g",
        stem="Explain why an ammeter should have a very low resistance and a voltmeter a very high resistance.",
        points=[P("an ammeter is in series, so its own resistance adds to the circuit; a low resistance means it hardly changes the current it is measuring", ["in series", "adds to the circuit", "would reduce the current", "hardly changes the current", "does not change the current", "not affect the current"]),
                P("a voltmeter is in parallel; a high resistance means it draws almost no current through itself", ["in parallel", "draws almost no current", "very little current", "negligible current", "takes no current", "does not divert"]),
                P("so the current and p.d. in the circuit stay almost the same as they would be without the meters", ["same as without", "does not disturb", "not affect the circuit", "accurate reading", "true value", "unchanged"])],
        min_points=2,
        model_answer="An ammeter is connected in series, so its own resistance is added to the circuit; it must have a very low resistance so that it hardly changes the current it is meant to measure. A voltmeter is connected in parallel across a component; it must have a very high resistance so that it draws almost no current through itself and does not alter the p.d. it is measuring.",
        hints=["Each meter is part of the circuit while it measures. How could each one disturb what it measures?",
               "A series meter adds resistance; a parallel meter provides an extra path.",
               "Explain the requirement for each meter."],
        keywords="ammeter in series, low R so current unchanged; voltmeter in parallel, high R so draws no current",
        sample_pass=["The ammeter is in series so a low resistance stops it reducing the current; the voltmeter is in parallel so a high resistance stops it drawing current",
                     "so that the meters do not disturb the circuit: the ammeter must not add resistance and the voltmeter must not divert current"],
        sample_fail=["So that they do not break", "Both should have high resistance to be safe"])

